#!/usr/bin/env python3
from pathlib import Path
import re,sys

if len(sys.argv)!=3: raise SystemExit('usage: integrate-SOT-turn01-base23-ui.py <clean-base22-intermediate.html> <base23.html>')
src=Path(sys.argv[1]).read_text()
for marker in ['TURN01_BASE22_CANONICAL_SELECTOR','async function openFolderSelector(opts)','async function renderIndex(p)','async function renderPlan(p)']:
    if src.count(marker)!=1: raise SystemExit(f'clean Base-22 integration contract failed for {marker}: {src.count(marker)}')

def span(text,name):
    ms=list(re.finditer(r'(?m)^(?:async\s+)?function\s+'+re.escape(name)+r'\s*\(',text))
    if len(ms)!=1: raise SystemExit(f'function {name} ambiguous {len(ms)}')
    a=ms[0].start(); b=text.find('{',ms[0].end()); d=0;q=None;e=False;i=b
    while i<len(text):
        c=text[i]
        if q:
            if e:e=False
            elif c=='\\':e=True
            elif c==q:q=None
        else:
            if c in "'\"`":q=c
            elif c=='{':d+=1
            elif c=='}':
                d-=1
                if d==0:return a,i+1
        i+=1
    raise SystemExit('unbalanced '+name)
def repl(text,name,val):
    a,b=span(text,name);return text[:a]+val.rstrip()+text[b:]

src=src.replace('/* TURN01_BASE22_CANONICAL_SELECTOR */','/* TURN01_BASE22_CANONICAL_SELECTOR */\n/* TURN01_BASE23_OWNER_GATE */',1)
css=r'''
/* TURN01_BASE23_OWNER_GATE */
.picker3{height:min(520px,68dvh)}.picker3 .pane{min-height:0}.picker3 .paneBody{min-height:0;overflow:auto}.availableTools{padding:8px;border-bottom:1px solid var(--line);flex:0 0 auto}.availableTools .input{padding:7px 9px}.selectedPaneBody{min-height:0;overflow:auto;flex:1;padding:8px}.selectorCreateBar{flex:0 0 auto;padding:8px;border-top:1px solid var(--line);display:flex;gap:6px}.selectorCreateBar input{min-width:0;flex:1}.planCurrent{border-color:#3f6488}.planPrevious{opacity:.78}.planRecovery{display:flex;align-items:center;justify-content:space-between;gap:10px}.planRecovery .btn{flex:0 0 auto}
'''
src=src.replace('</style>',css+'\n</style>',1)

selector=r'''async function openFolderSelector(opts){let role=opts.role||'source',multi=role==='source',selected=[...(opts.selected||[])],volumes=[],currentPath='',lastData=null,filter='',rootId='canonicalFolderMount';let commitLabel=opts.doneLabel||(role==='source'?'Save Sources':role==='target'?'Save Target':role==='backup'?'Save Backup':'Use selection');openModal(opts.title||'Select folders',`<div id="${rootId}" class="empty">Loading storage catalog…</div>`,`<button class="btn" data-close>Cancel</button><button id="selectorCommit" class="btn primary" disabled>${esc(commitLabel)}</button>`);let root=$(rootId);let cap=v=>v==null?'capacity unavailable':`${bytes(v)} free`;function available(d){let chosen=new Set(selected),rows=[];if(!chosen.has(d.path))rows.push({name:d.volume?.name||'Volume root',path:d.path,root:true});for(let f of(d.folders||[]))if(!chosen.has(f.path))rows.push(f);return rows}function draw(d){lastData=d;let active=d.volume?.path||'',needle=filter.trim().toLowerCase(),avail=available(d).filter(f=>!needle||String(f.name||f.path).toLowerCase().includes(needle));root.className='';root.innerHTML=`<div class="picker3"><div class="pane"><div class="paneHead">Volumes <button id="refreshCatalog" class="mini" style="float:right">↻</button></div><div class="paneBody">${volumes.map(v=>`<button class="pickBtn ${active===v.path?'active':''}" data-volume="${esc(v.path)}"><b>${esc(v.name)}</b><small>${cap(v.free_bytes)}</small></button>`).join('')}</div></div><div class="pane"><div class="paneHead">Available folders</div><div class="availableTools"><input id="availableFolderSearch" class="input" placeholder="Search folders…" value="${esc(filter)}"></div><div class="pathBar">${esc(d.path)}</div><div class="paneBody">${d.parent?`<div class="folderRow"><button data-browse="${esc(d.parent)}">..</button><span></span></div>`:''}${avail.map(f=>`<div class="folderRow"><button data-browse="${esc(f.path)}">${esc(f.name||f.path)}</button><button class="move" data-add="${esc(f.path)}">Add →</button></div>`).join('')||'<div class="empty">No matching available folders.</div>'}</div></div><div class="pane"><div class="paneHead">Selected</div><div class="selectedPaneBody">${selected.map(p=>`<div class="selectedItem"><span class="mono">${esc(p)}</span><button class="btn" data-remove="${esc(p)}">Remove</button></div>`).join('')||'<div class="empty">Nothing selected.</div>'}</div><div class="selectorCreateBar"><input id="selectorFolderName" class="input" placeholder="New folder"><button id="selectorCreate" class="btn">+ Create</button></div></div></div>`;let commit=$('selectorCommit');if(commit)commit.disabled=!selected.length;document.querySelectorAll('[data-volume]').forEach(n=>n.onclick=()=>render(n.dataset.volume));document.querySelectorAll('[data-browse]').forEach(n=>n.onclick=()=>render(n.dataset.browse));document.querySelectorAll('[data-add]').forEach(n=>n.onclick=()=>{let p=n.dataset.add;if(multi){if(!selected.includes(p))selected.push(p)}else selected=[p];draw(lastData)});document.querySelectorAll('[data-remove]').forEach(n=>n.onclick=()=>{selected=selected.filter(x=>x!==n.dataset.remove);draw(lastData)});$('availableFolderSearch').oninput=e=>{filter=e.target.value;draw(lastData);let s=$('availableFolderSearch');s.focus();s.setSelectionRange(s.value.length,s.value.length)};$('refreshCatalog').onclick=async()=>{let v=await api('/turn01/volumes?refresh=1');volumes=v.volumes||[];await render(currentPath,true)};$('selectorCreate').onclick=async()=>{let name=$('selectorFolderName').value.trim();if(!name)return;try{let made=await api('/turn01/fs/folder',{method:'POST',body:JSON.stringify({parent:d.path,name})});if(multi){if(!selected.includes(made.path))selected.push(made.path)}else selected=[made.path];await render(d.path)}catch(e){toast(e.message)}}}async function render(pathValue,refresh=false){try{currentPath=pathValue;filter='';let d=await api(`/turn01/fs?path=${encodeURIComponent(pathValue)}${refresh?'&refresh=1':''}`);draw(d)}catch(e){root.className='errorBox';root.textContent=e.message}}$('selectorCommit').onclick=()=>{let result=[...selected];closeModal();opts.onDone(result)};try{let v=await api('/turn01/volumes');volumes=v.volumes||[];let initial=(selected.find(x=>volumes.some(v=>x===v.path||x.startsWith(v.path+'/')))||volumes[0]?.path);if(!initial){root.className='errorBox';root.textContent='No storage volumes discovered.';return}await render(initial)}catch(e){root.className='errorBox';root.textContent=e.message}}'''
src=repl(src,'openFolderSelector',selector)

index_fn=r'''async function renderIndex(p,silent=false){let c=$('content');if(!silent)c.innerHTML='<div class="empty">Loading index status…</div>';try{let s=await api(`/projects/${encodeURIComponent(p.project_token)}/fingerprint/status`),r=s.run||{},pr=s.progress||{};c.innerHTML=`<div class="metrics"><div class="metric"><b>${Number(r.files_discovered||0).toLocaleString()}</b><span>Files discovered</span></div><div class="metric"><b>${Number(r.files_processed||0).toLocaleString()}</b><span>Files processed</span></div><div class="metric"><b>${bytes(r.bytes_processed||0)}</b><span>Bytes processed</span></div><div class="metric"><b>${esc(s.state||'NotStarted')}</b><span>Activity</span></div></div><div class="section"><div class="sectionHead"><h2>Index / Fingerprint</h2></div><div class="sectionBody"><div class="progress"><i style="width:${Number(pr.bytes_percent||0)}%"></i></div><p class="muted">${pct(pr.bytes_percent||0)} · ${esc(r.current_item||r.current_source||(s.state==='Closed'?'Complete':'Idle'))}</p><div class="actions"><button class="btn primary" id="idxStart">${s.state==='Closed'?'Re-index':'Start / Continue'}</button><button class="btn" id="idxPause" ${['Queued','WIP'].includes(s.state)?'':'disabled'}>Pause</button><button class="btn danger" id="idxStop" ${['Queued','WIP','Paused'].includes(s.state)?'':'disabled'}>Stop</button></div></div></div>`;$('idxStart').onclick=()=>runAction(p.project_token,s.state==='Closed'?'restart':'continue');if(!$('idxPause').disabled)$('idxPause').onclick=()=>runAction(p.project_token,'pause');if(!$('idxStop').disabled)$('idxStop').onclick=()=>runAction(p.project_token,'stop')}catch(e){if(!silent)c.innerHTML=`<div class="errorBox">${esc(e.message)}</div>`}}'''
src=repl(src,'renderIndex',index_fn)

plan_fn=r'''async function renderPlan(p){let c=$('content');c.innerHTML='<div class="empty">Loading plan…</div>';try{let[d,review]=await Promise.all([api(`/turn01/projects/${encodeURIComponent(p.project_token)}/plan`),api(`/turn01/projects/${encodeURIComponent(p.project_token)}/review`)]),items=d.items||[],current=Number(d.evidence_revision||-1)===Number(p.evidence_revision||0)&&d.state!=='stale'&&d.state!=='none',noEvidence=Number(review.files||0)===0;let currentHtml=current?`<div class="section planCurrent"><div class="sectionHead"><h2>Current Plan</h2><span class="good">${esc(d.state)}</span></div><div class="sectionBody"><p class="muted">Evidence revision ${Number(d.evidence_revision||0)} · ${items.length.toLocaleString()} plan items</p><div class="list">${items.slice(0,100).map(i=>`<div class="row"><div><b>${esc(i.action||'action')}</b><small class="mono">${esc(i.source_path||i.content_sha256||'')}</small></div><span>${esc(i.state||'')}</span></div>`).join('')||'<div class="empty">Current plan contains no actions.</div>'}</div></div></div>`:'';let staleHtml=!current&&d.state!=='none'?`<div class="section planPrevious"><div class="sectionHead"><h2>Previous / Stale Plan</h2><span class="warn">Not executable</span></div><div class="sectionBody"><p class="muted">This plan belongs to evidence revision ${Number(d.evidence_revision||0)} and is retained only as history.</p><div class="list">${items.slice(0,40).map(i=>`<div class="row"><div><b>${esc(i.action||'action')}</b><small class="mono">${esc(i.source_path||i.content_sha256||'')}</small></div><span>${esc(i.state||'')}</span></div>`).join('')}</div></div></div>`:'';c.innerHTML=`<div class="section"><div class="sectionHead"><h2>Plan</h2><button id="generatePlan" class="btn primary">Generate current plan</button></div><div class="sectionBody" id="planStatus">${noEvidence?`<div class="notice planRecovery"><div><b>Current fingerprint evidence is unavailable.</b><div class="muted">The current project scope has no usable fingerprint records. Re-index the current Sources, then generate the plan again.</div></div><button id="planReindex" class="btn">Re-index now</button></div>`:`<p class="muted">${current?'The current executable plan is shown below.':'No current executable plan exists yet.'}</p>`}</div></div>${currentHtml}${staleHtml}`;if($('planReindex'))$('planReindex').onclick=()=>runAction(p.project_token,'restart');$('generatePlan').onclick=async()=>{try{let made=await api(`/turn01/projects/${encodeURIComponent(p.project_token)}/plan`,{method:'POST',body:'{}'});toast('Current plan generated');await load();let fresh=selectedProject();if(fresh){state.tab='plan';state.projectTab='plan';renderPlan(fresh)}}catch(e){let box=$('planStatus');box.innerHTML=`<div class="errorBox planRecovery"><div><b>Plan was not generated.</b><div>${esc(e.message)}</div>${/no current evidence/i.test(e.message)?'<div class="muted">Re-index the current Sources to create current fingerprint evidence.</div>':''}</div>${/no current evidence/i.test(e.message)?'<button id="planReindex" class="btn">Re-index now</button>':''}</div>`;if($('planReindex'))$('planReindex').onclick=()=>runAction(p.project_token,'restart')}}}catch(e){c.innerHTML=`<div class="errorBox">${esc(e.message)}</div>`}}'''
src=repl(src,'renderPlan',plan_fn)

# Replace polling tail so completed Index is never periodically rerendered.
pat=re.compile(r"load\(\);setInterval\(async\(\)=>\{try\{let \[p,r\]=await Promise\.all\(\[api\('/projects'\),api\('/rollup'\)\]\);state\.projects=Array\.isArray\(p\)\?p:\(p\.projects\|\|\[\]\);state\.rollup=r;renderCards\(\);let psel=selectedProject\(\);if\(psel&&state\.tab==='index'\)renderIndex\(psel\)\}catch\{\}\},3000\);")
replacement="load();setInterval(async()=>{try{let [p,r]=await Promise.all([api('/projects'),api('/rollup')]);state.projects=Array.isArray(p)?p:(p.projects||[]);state.rollup=r;renderCards();let psel=selectedProject();if(psel&&state.tab==='index'&&['Queued','WIP','Paused'].includes(projectState(psel)))renderIndex(psel,true)}catch{}},3000);"
src,n=pat.subn(replacement,src,count=1)
if n!=1: raise SystemExit(f'polling-tail replacement failed count={n}')

# Qualification contracts.
for m in ['TURN01_BASE23_OWNER_GATE','availableFolderSearch','selectedPaneBody','selectorCommit','Current Plan','Previous / Stale Plan','Re-index now',"['Queued','WIP','Paused'].includes(projectState(psel))"]:
    if m not in src: raise SystemExit('missing Base23 contract '+m)
if 'selectorDone' in src: raise SystemExit('embedded selectorDone survived')
Path(sys.argv[2]).write_text(src)
print('Base-23 UI generated from clean pre-base integration chain')
